# 🗺️ YEAR 1 GEOGRAPHY LAB: Using the 4 Compass Directions
compass = {'North': (0, -1), 'East': (1, 0), 'South': (0, 1), 'West': (-1, 0)}
for direction, step in compass.items():
    print(f'Compass Direction: {direction:<6} -> Map Step: {step}')
assert len(compass) == 4
